"use client";

import { useEffect, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ArrowSquareOutIcon as PhArrowSquareOut } from "@phosphor-icons/react";

function ShimmerBlock({ className }: { className: string }) {
  return (
    <div className={`relative overflow-hidden rounded-md bg-slate-200 dark:bg-slate-700 ${className}`}>
      <motion.span
        aria-hidden
        className="absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/60 to-transparent dark:via-white/10"
        animate={{ x: ["-100%", "100%"] }}
        transition={{ duration: 1.4, repeat: Infinity, ease: "linear" }}
      />
    </div>
  );
}

function ExternalLinkIcon() {
  return <PhArrowSquareOut size={12} aria-hidden />;
}

function ThumbnailMock() {
  return (
    <div className="absolute inset-0 flex flex-col gap-1.5 bg-gradient-to-br from-emerald-50 to-slate-100 p-3 dark:from-emerald-500/10 dark:to-neutral-900">
      <div className="flex gap-1" aria-hidden>
        <span className="h-1.5 w-1.5 rounded-full bg-slate-300 dark:bg-slate-600" />
        <span className="h-1.5 w-1.5 rounded-full bg-slate-300 dark:bg-slate-600" />
        <span className="h-1.5 w-1.5 rounded-full bg-slate-300 dark:bg-slate-600" />
      </div>
      <div className="h-2.5 w-2/5 rounded-sm bg-emerald-300/70 dark:bg-emerald-500/30" aria-hidden />
      <div className="mt-1 grid flex-1 grid-cols-3 gap-1.5" aria-hidden>
        <div className="col-span-1 rounded-sm bg-white/70 dark:bg-white/10" />
        <div className="col-span-2 flex flex-col gap-1.5">
          <div className="h-2 w-4/5 rounded-sm bg-white/70 dark:bg-white/10" />
          <div className="h-2 w-3/5 rounded-sm bg-white/70 dark:bg-white/10" />
          <div className="flex-1 rounded-sm bg-white/50 dark:bg-white/5" />
        </div>
      </div>
    </div>
  );
}

export function LinkPreviewCard({
  url,
  title,
  description,
  image,
  imageAlt,
  credit,
  liveUrl,
}: {
  url: string;
  title: string;
  description: string;
  image?: string;
  imageAlt?: string;
  credit?: { name: string; href: string };
  liveUrl?: string;
}) {
  const shouldReduceMotion = useReducedMotion();
  const [timerResolved, setTimerResolved] = useState(false);
  const [iframeLoaded, setIframeLoaded] = useState(false);
  const resolved = shouldReduceMotion === true || (liveUrl ? iframeLoaded : timerResolved);
  const domain = url.split("/")[0];

  useEffect(() => {
    if (shouldReduceMotion || liveUrl) return;
    const timer = window.setTimeout(() => setTimerResolved(true), 900);
    return () => window.clearTimeout(timer);
  }, [shouldReduceMotion, liveUrl]);

  return (
    <motion.div
      role="link"
      tabIndex={0}
      aria-label={title}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") e.preventDefault();
      }}
      whileHover={shouldReduceMotion ? undefined : { y: -3 }}
      transition={{ type: "spring", stiffness: 380, damping: 28 }}
      className="group block w-full max-w-sm cursor-pointer overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm transition-shadow duration-300 hover:shadow-lg focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-slate-700 dark:bg-neutral-950"
    >
      <div className="relative h-28 w-full overflow-hidden bg-slate-100 dark:bg-neutral-900">
        <div className="absolute inset-0 transition-transform duration-500 ease-out group-hover:scale-105">
          {liveUrl ? (
            <iframe
              src={liveUrl}
              title=""
              aria-hidden
              tabIndex={-1}
              loading="lazy"
              onLoad={() => setIframeLoaded(true)}
              className="pointer-events-none border-0"
              style={{ width: "400%", height: "400%", transform: "scale(0.25)", transformOrigin: "top left" }}
            />
          ) : image ? (
            <img src={image} alt={imageAlt ?? ""} className="h-full w-full object-cover" />
          ) : (
            <ThumbnailMock />
          )}
        </div>
        <AnimatePresence>
          {!resolved && (
            <motion.div
              key="loading"
              exit={{ opacity: 0 }}
              transition={{ duration: 0.3 }}
              className="absolute inset-0 bg-slate-100 p-3 dark:bg-neutral-900"
            >
              <ShimmerBlock className="h-full w-full" />
            </motion.div>
          )}
        </AnimatePresence>
        {resolved && image && credit && (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              window.open(credit.href, "_blank", "noopener,noreferrer");
            }}
            className="absolute bottom-1.5 right-1.5 z-10 rounded-full bg-black/55 px-2 py-0.5 text-[10px] font-medium text-white backdrop-blur-sm transition-colors hover:bg-black/75"
          >
            Photo: {credit.name}
          </button>
        )}
      </div>

      <div className="p-4">
        <AnimatePresence mode="wait">
          {resolved ? (
            <motion.div
              key="resolved-text"
              initial={shouldReduceMotion ? { opacity: 1 } : { opacity: 0, y: 4 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
            >
              <div className="flex items-center gap-1.5">
                <span className="flex h-4 w-4 shrink-0 items-center justify-center rounded-[4px] bg-emerald-600 text-[9px] font-bold text-white">
                  {domain.charAt(0).toUpperCase()}
                </span>
                <span className="truncate text-xs uppercase tracking-wide text-slate-400 dark:text-slate-500">{domain}</span>
                <span className="ml-auto text-slate-400 opacity-0 transition-opacity duration-200 group-hover:opacity-100 dark:text-slate-500">
                  <ExternalLinkIcon />
                </span>
              </div>
              <h3 className="mt-1.5 truncate text-[15px] font-semibold text-slate-900 dark:text-white">{title}</h3>
              <p className="mt-1 text-sm leading-relaxed text-slate-500 line-clamp-2 dark:text-slate-400">{description}</p>
            </motion.div>
          ) : (
            <motion.div key="loading-text" exit={{ opacity: 0 }} transition={{ duration: 0.2 }} className="flex flex-col gap-2">
              <ShimmerBlock className="h-3 w-1/3" />
              <ShimmerBlock className="h-3.5 w-4/5" />
              <ShimmerBlock className="h-3 w-full" />
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.div>
  );
}
